import{_ as a,H as l,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"12 | 再回首：如何实现SpringMVC？","description":"","frontmatter":{},"headers":[{"level":3,"title":"MVC 重点回顾","slug":"mvc-重点回顾","link":"#mvc-重点回顾","children":[]},{"level":3,"title":"那我们在课程中是怎么实现 MVC 的呢？","slug":"那我们在课程中是怎么实现-mvc-的呢","link":"#那我们在课程中是怎么实现-mvc-的呢","children":[]},{"level":3,"title":"07｜原始 MVC：如何通过单一的 Servlet 拦截请求分派任务？","slug":"_07-原始-mvc-如何通过单一的-servlet-拦截请求分派任务","link":"#_07-原始-mvc-如何通过单一的-servlet-拦截请求分派任务","children":[]},{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":3,"title":"参考答案","slug":"参考答案","link":"#参考答案","children":[]},{"level":3,"title":"08｜整合 IoC 和 MVC：如何在 Web 环境中启动 IoC 容器？","slug":"_08-整合-ioc-和-mvc-如何在-web-环境中启动-ioc-容器","link":"#_08-整合-ioc-和-mvc-如何在-web-环境中启动-ioc-容器","children":[]},{"level":3,"title":"思考题","slug":"思考题-1","link":"#思考题-1","children":[]},{"level":3,"title":"参考答案","slug":"参考答案-1","link":"#参考答案-1","children":[]},{"level":3,"title":"09｜分解 Dispatcher：如何把专门的事情交给专门的部件去做？","slug":"_09-分解-dispatcher-如何把专门的事情交给专门的部件去做","link":"#_09-分解-dispatcher-如何把专门的事情交给专门的部件去做","children":[]},{"level":3,"title":"思考题","slug":"思考题-2","link":"#思考题-2","children":[]},{"level":3,"title":"参考答案","slug":"参考答案-2","link":"#参考答案-2","children":[]},{"level":3,"title":"10｜数据绑定: 如何自动转换传入的参数？","slug":"_10-数据绑定-如何自动转换传入的参数","link":"#_10-数据绑定-如何自动转换传入的参数","children":[]},{"level":3,"title":"思考题","slug":"思考题-3","link":"#思考题-3","children":[]},{"level":3,"title":"参考答案","slug":"参考答案-3","link":"#参考答案-3","children":[]},{"level":3,"title":"11｜ModelAndView ：如何将处理结果返回到前端？","slug":"_11-modelandview-如何将处理结果返回到前端","link":"#_11-modelandview-如何将处理结果返回到前端","children":[]},{"level":3,"title":"参考答案","slug":"参考答案-4","link":"#参考答案-4","children":[]}],"relativePath":"手把手带你写一个MiniSpring/12｜再回首：如何实现SpringMVC？.md","filePath":"手把手带你写一个MiniSpring/12｜再回首：如何实现SpringMVC？.md","lastUpdated":1795557483000}'),r={name:"手把手带你写一个MiniSpring/12｜再回首：如何实现SpringMVC？.md"};function n(o,e,p,s,h,d){return l(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_12-再回首-如何实现springmvc" tabindex="-1">12 | 再回首：如何实现SpringMVC？ <a class="header-anchor" href="#_12-再回首-如何实现springmvc" aria-label="Permalink to &quot;12 | 再回首：如何实现SpringMVC？&quot;">​</a></h1><p>你好，我是郭屹。</p><p>恭喜你学完 MiniSpring 的第二部分——MVC 了。你是不是跟着我的脚步自己也实现了一个MVC 呢？如果已经完成了，欢迎你把你的实现代码放到评论区，我们一起交流讨论。</p><p>为了让你更好地掌握这部分内容，我们来对这一整章做一个重点回顾。</p><h3 id="mvc-重点回顾" tabindex="-1">MVC 重点回顾 <a class="header-anchor" href="#mvc-重点回顾" aria-label="Permalink to &quot;MVC 重点回顾&quot;">​</a></h3><p>MVC 是 Spring 框架的核心组成部分之一，负责实现一个 Web 应用程序的模型视图控制器模式。Spring 框架提供了丰富的组件和工具，而 MVC 负责处理一个 Web 应用程序中的核心过程，例如请求处理、数据转换、模板渲染和视图管理等。而 MVC 和 Spring 的结合，就像是车与引擎的结合一样，给 Web 应用程序提供了强大而且可靠的性能和灵活性，让我们能够快速、方便地搭建高性能、可靠的 Web 应用程序。</p><p>因为 Spring 是 Java 实现的，也因为发明人 Rod Johnson 先生自己是 Java 团队 Servlet 规范的专家组成员，所以很自然，他的 MVC 的实现是基于 Servlet 的。利用 Servlet 的机制，把这种功效发挥到了极致，快速构造了完整的 Web 程序结构，让我们大开眼界。</p><h3 id="那我们在课程中是怎么实现-mvc-的呢" tabindex="-1">那我们在课程中是怎么实现 MVC 的呢？ <a class="header-anchor" href="#那我们在课程中是怎么实现-mvc-的呢" aria-label="Permalink to &quot;那我们在课程中是怎么实现 MVC 的呢？&quot;">​</a></h3><p>首先我们利用 Servlet 机制，用一个单一的 Servlet 拦截所有请求，由它来分派任务，这样实现了原始的 MVC 结构。然后呢，我们把 MVC 和 IoC 结合在一起，在 Servlet 容器启动的时候，给上下文环境里注入 IoC 容器，使得在 Servlet 里可以访问到 IoC 容器里的 Bean。</p><p>之后我们进一步解耦 MVC 结构，独立出请求处理器，还用一个简洁统一的注解方式，把 Web请求方便地定位到后台处理的类和方法里，实现 Spring 的 RequestHandler。</p><p>在前后台打通的时候，实现数据参数的自动转换，也就是说先把 Web 请求的传入参数，自动地从文本转换成对象，实现数据绑定功能。对于返回数据，也自动根据用户需求进行格式化转换，这样实现了 Spring 里面的 data binder 和 data conversion。最后回到前端 View，如果有前端引擎，在 Spring 中引用，把数据自动渲染到前端。</p><p>我们可以利用 Servlet 机制、MVC 结构、IoC 容器、RequestHandler 和数据绑定等功能，确保前后台的有效沟通和良好的交互体验，实现一个高效可靠的 Web 应用程序。你学会了吗？</p><p>最后，我们再来看一下这一章的几道思考题，我在文稿里都给出了参考答案。我建议你也可以把你的思考分享在留言区，看看自己的思路是不是对的。题目我也就不一道一道地说了，你在做完思考题之后，自己来对比。</p><h3 id="_07-原始-mvc-如何通过单一的-servlet-拦截请求分派任务" tabindex="-1">07｜原始 MVC：如何通过单一的 Servlet 拦截请求分派任务？ <a class="header-anchor" href="#_07-原始-mvc-如何通过单一的-servlet-拦截请求分派任务" aria-label="Permalink to &quot;07｜原始 MVC：如何通过单一的 Servlet 拦截请求分派任务？&quot;">​</a></h3><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>我们在 MVC 中也使用了 Bean 这个概念，它跟我们以前章节中的 Bean 是什么关系？</p><h3 id="参考答案" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>MVC（Model-View-Controller）和 IoC（Inversion of Control）是两个不同的设计模式，它们都使用“Bean”这个概念，但是在不同的层级和实现方式上有所不同。</p><ul><li><p>在 MVC 中，“Bean”通常指代模型对象。模型对象是业务逻辑层的核心，用于实现数据访问和业务逻辑处理等功能。在 MVC 中，模型对象通常是由控制器（Controller）创建并向视图（View）传递的。</p></li><li><p>在 IoC 中，“Bean”指代由 IoC 容器管理的对象。IoC 容器负责创建及管理应用程序中的所有 Bean 对象。通过 IoC 容器，应用程序能够实现“控制反转”，即由 IoC 容器统一管理和调度应用程序中的各个组件。在 IoC 中，Bean 是由 IoC 容器创建、初始化、配置和装配的。</p></li></ul><p>因此，尽管 MVC 和 IoC 都使用了“Bean”这个概念，但它们的含义及在系统中的作用是不同的。MVC 中的 Bean 一般是 Web 相关的业务逻辑，IoC 中的 Bean 可能是一些更加基础性的逻辑。从 MVC 中可以访问到 IoC 容器中的 Bean。</p><h3 id="_08-整合-ioc-和-mvc-如何在-web-环境中启动-ioc-容器" tabindex="-1">08｜整合 IoC 和 MVC：如何在 Web 环境中启动 IoC 容器？ <a class="header-anchor" href="#_08-整合-ioc-和-mvc-如何在-web-环境中启动-ioc-容器" aria-label="Permalink to &quot;08｜整合 IoC 和 MVC：如何在 Web 环境中启动 IoC 容器？&quot;">​</a></h3><h3 id="思考题-1" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-1" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>我们看到从 Dispatcher 里可以访问 WebApplicationContext 里管理的 Bean，那通过WebApplicationContext 可以访问 Dispatcher 内管理的 Bean 吗？</p><h3 id="参考答案-1" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案-1" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>不可以。</p><p>Servlet 容器启动的时候，按照时序，是先启动 Listener，在 Listener 的初始化过程中创建 IoC容器，放到 ServletContext 里，这就是 WAC。这之后再初始化的 Servlet。所以 Dispatcher可以访问到 WAC，但是 WAC 访问不到 DispatcherServlet，这个是单向的。</p><h3 id="_09-分解-dispatcher-如何把专门的事情交给专门的部件去做" tabindex="-1">09｜分解 Dispatcher：如何把专门的事情交给专门的部件去做？ <a class="header-anchor" href="#_09-分解-dispatcher-如何把专门的事情交给专门的部件去做" aria-label="Permalink to &quot;09｜分解 Dispatcher：如何把专门的事情交给专门的部件去做？&quot;">​</a></h3><h3 id="思考题-2" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-2" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>目前，我们只支持了 GET 方法，你能不能尝试自己增加 POST 方法。想一想，需要改变现有的程序结构吗？</p><h3 id="参考答案-2" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案-2" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>增加 POST 方法支持不需要改变现有程序结构。因为我们的 DispatcherServlet 现在统一用service() 方法处理所有请求，之后调用 doDispatch() 方法，最后通过this.handlerMapping.getHandler() 找到需要调用的方法。无论对于 GET 还是 POST，都是同样的流程，统一由 handlerMapping 来区分不同的调用方法。</p><p>所以如果要区分 GET 和 POST，则可以在 RequestMapping 注解上增加 METHOD 属性，表示 GET 还是 POST，然后 handlerMapping.getHandler() 中根据 GET 和 POST 匹配实际的调用方法。</p><h3 id="_10-数据绑定-如何自动转换传入的参数" tabindex="-1">10｜数据绑定: 如何自动转换传入的参数？ <a class="header-anchor" href="#_10-数据绑定-如何自动转换传入的参数" aria-label="Permalink to &quot;10｜数据绑定: 如何自动转换传入的参数？&quot;">​</a></h3><h3 id="思考题-3" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-3" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>我们现在的实现是把 request 里面的参数值，按照内部的次序隐含地自动转成后台调用方法参数对象中的某个属性值，那么可不可以使用一个手段，让程序员手动指定某个调用方法的参数跟哪个 request 参数进行绑定呢？</p><h3 id="参考答案-3" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案-3" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>参数绑定的处理，是在 RequestMappingHandlerAdatper 的 invokeHandlerMethod() 方法中处</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理的，它拿到调用方法的所有参数，一个参数一个参数进行绑定： WebDataBinder wdb =</span></span>
<span class="line"><span>binderFactory.createBinder(request, methodParamObj,</span></span>
<span class="line"><span>methodParameter.getName());。所以我们在这里可以考虑给参数增加一个注解</span></span></code></pre></div><p>@RequestParam。对于带有这个注解的参数，就不是隐含地按照参数名去匹配，而是按照指定的名字去 request 中匹配。</p><h3 id="_11-modelandview-如何将处理结果返回到前端" tabindex="-1">11｜ModelAndView ：如何将处理结果返回到前端？ <a class="header-anchor" href="#_11-modelandview-如何将处理结果返回到前端" aria-label="Permalink to &quot;11｜ModelAndView ：如何将处理结果返回到前端？&quot;">​</a></h3><p>现在返回的数据只支持 Date、Number 和 String 三种类型，如何扩展到更多的数据类型？现在也只支持 JSP，如何扩展到别的前端？</p><h3 id="参考答案-4" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案-4" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p>返回数据的格式处理是通过 ObjectMapper 来实现的。我们有一个默认实现DefaultObjectMapper，只要在它的 writeValuesAsString() 里判断数据类型的时候，增加别的类型就可以了。</p><p>对于 JSP 之外的 View，我们现在的结构是可扩展的。只要自己另外实现一个 View 和一个View resolver 即可。</p>`,44)])])}const v=a(r,[["render",n]]);export{u as __pageData,v as default};
